import {readFileSync, writeFileSync, mkdtempSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const here=fileURLToPath(new URL('.',import.meta.url));
const root=process.env.REPORT_SOURCE_DIR;if(!root)throw new Error('set REPORT_SOURCE_DIR to the directory holding aws_costs/ and dev_performance/');
const date=(s,n)=>{const d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const accounts=[0,1].map(i=>{const key=i?'beta':'alpha', factor=i?2:1, monthly={}, daily={}, usage={}, usage_week={}, tag_service={}, tags={}, tags_daily={}, region={};
 for(let m=1;m<=11;m++){const month=`2026-${String(m).padStart(2,'0')}-01`, base=(m===11?40:100)*factor;monthly[month]={'Amazon Simple Storage Service':base,'AWS Lambda':base/2,Tax:base*.15};usage[month]={'AWS Lambda||Requests':base/2};region[month]={'us-east-1':base*1.65};for(const tag of ['Client','Project','Environment']) {((tag_service[tag]||={})[month]||={})['North||Amazon Simple Storage Service']=base;tag_service[tag][month]['(untagged)||AWS Lambda']=base/2;tag_service[tag][month]['(untagged)||Tax']=base*.15;((tags[tag]||={})[month]||={}).North=base;}}
 for(let n=2;n<=8;n++){const d=date('2026-11-20',-n);daily[d]={'Amazon Simple Storage Service':5*factor,'AWS Lambda':2*factor};usage_week[d]={'AWS Lambda||Requests':2*factor};((tags_daily.Project||={})[d]||={}).North=5*factor;}
 return {key,label:i?'Beta':'Alpha',profile:key,account_id:i?'222222222222':'111111111111',note:'synthetic',costs:{monthly,daily,usage,usage_week,region,tags,tag_service,tags_daily,tag_keys:['Client','Project','Environment'],tag_aliases:{Client:{north:'North'}},billed_monthly:{'2026-11-01':40*factor},billed_daily:{},credits_monthly:{'2026-11-01':{'AWS Lambda':-20*factor}},credits_daily:{},refunds_monthly:{},refunds_daily:{},forecast_rest_of_month:120*factor,estimated_days:[],unknown_record_types:[]},resources:[{account:key,status:i?'idle':'dead',kind:'Disk',name:`fake-disk-${key}`,id:`disk-${key}`,project:'North',region:'us-east-1',monthly:10*factor,recoverable:8*factor,evidence:'unused',state:'available'}],reservations:[],credit_grants:[{description:'Synthetic grant',remaining:500*factor,initial:600*factor,end:'2027-12-01',status:'ENABLED'}],credit_grants_error:null,collected_at:'2026-11-20',inventory_at:'2026-11-20',stale:null};});
accounts[0].stale='refresh failed'; accounts[0].costs.unknown_record_types=['SyntheticCharge'];
for(const a of accounts){a.costs.credits_monthly['2026-10-01']={'AWS Lambda':-165*(a.key==='beta'?2:1)};a.credit_grants[0].remaining=50*(a.key==='beta'?2:1);}
const data={today:'2026-11-20',generated:'2026-11-20',lookback_days:14,accounts};
writeFileSync(join(here,'fixture.json'),JSON.stringify(data,null,2)+'\n');
const read=p=>readFileSync(p,'utf8');const source=join(root,'aws_costs');
const html=read(join(source,'template.html')).replace('__CSS__',()=>read(join(root,'dev_performance/report.css'))).replace('__AWSCSS__',()=>read(join(source,'aws.css'))).replace('__JS__',()=>read(join(source,'app.js'))).replaceAll('__TODAY__',data.today).replace('__DATA__',()=>JSON.stringify(data).replaceAll('</','<\\/'));
const dir=mkdtempSync(join(tmpdir(),'aws-golden-'));try{const page=join(dir,'index.html');writeFileSync(page,html);const expected={};for(const view of ['both','alpha','beta']){const dom=execFileSync('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless','--disable-gpu','--no-sandbox','--disable-extensions','--dump-dom',`file://${page}?view=${view}`],{encoding:'utf8',stdio:['ignore','pipe','ignore'],maxBuffer:10_000_000});
 const section=(id,next)=>dom.split(`id="${id}"`)[1]?.split(next)[0]||''; const text=s=>s.replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim(); const stats=[...section('stats','id="compare"').matchAll(/<div class="stat"><div class="v [^"]*">([\s\S]*?)<\/div><div class="k">([\s\S]*?)<\/div>/g)].map(m=>({label:text(m[2]),value:text(m[1])}));
 const svc=section('svcTable','</tbody>');const services=[...svc.matchAll(/<tr class="svc"[^>]*>([\s\S]*?)<\/tr>/g)].map(m=>{const cells=[...m[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(x=>text(x[1]));return {name:cells[0],account:cells[1],rr:cells[4]};});
 const pivot=section('pvTable','</table>');const match=pivot.match(/<tr class="tot">([\s\S]*?)<\/tr>/);const totals=match?[...match[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(x=>text(x[1])):[]; const notes=section('notes','</section>');const callouts=[...notes.matchAll(/<div class="call(?: warn)?"><h4>([\s\S]*?)<\/h4><p>([\s\S]*?)<\/p><\/div>/g)].map(m=>({title:text(m[1]),text:text(m[2])})); if(!stats.length||!services.length||!totals.length||!callouts.length) throw Error(`Failed to extract ${view}`); expected[view]={stats,services,totals,callouts}; }
 writeFileSync(join(here,'expected.json'),JSON.stringify(expected,null,2)+'\n');}finally{rmSync(dir,{recursive:true,force:true});}
